/* Level overlay code; generated by `decomp overlays stubs`, stubs replaced by C as functions are matched. */
#include "types.h"
#include "asm.h"

/* Ported from rac1-decomp (src/overlays/shared/stash_00295010.c: func_L00_00295010), where it is exact; names translated to the US level program. */

typedef struct {
    char *base;
    int   limit;
    int   unk8;
    int   unkC;
} StashSlot;

extern StashSlot l00_stash_slots[] __asm__("D_L00_001C12D8");
extern s32       sceSifSetDma(struct sceSifDmaData *transfer, s32 priority);

/* SIF-DMAs size quadwords from slot base + off; -3 for a bad or empty slot, -1 past its limit. */
int send_dma_to_stash_slot(int          dma_source_address,
                           unsigned int slot,
                           int          slot_offset_quadwords,
                           int          size) __asm__("FUN_L00_00293d38");

int send_dma_to_stash_slot(int          dma_source_address,
                           unsigned int slot,
                           int          slot_offset_quadwords,

                           int size) {
    int req[4];
    int slot_limit_quadwords;
    if (slot >= 0x40)
        return -3;
    slot_limit_quadwords = l00_stash_slots[slot].limit;
    if (slot_limit_quadwords == 0)
        return -3;
    if (slot_limit_quadwords < slot_offset_quadwords + size)
        return -1;
    req[0] = dma_source_address;
    req[1] = (int)(l00_stash_slots[slot].base + slot_offset_quadwords * 16);
    req[2] = size * 16;
    req[3] = 0;
    sceSifSetDma(req, 1);
    return 0;
}
